/* From Uiverse.io by david-mohseni - Tags: card */
.__UIV_SCOPE__ .flip {
  box-shadow: 0 0 10px rgba(128, 128, 128, 0.5);
  padding: 1em;
  width: 190px;
  height: 254px;
  transform-style: preserve-3d;
  transition: 3s ease;
}

.__UIV_SCOPE__ .flip:hover {
  transform: rotateY(180deg);
}
/* Content */
.__UIV_SCOPE__ .flip .content {
  transform-style: preserve-3d;
}

.__UIV_SCOPE__ .flip .back, .__UIV_SCOPE__ .flip .front {
  transform-style: preserve-3d;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .flip .back {
  transform: rotateY(180deg);
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}

.__UIV_SCOPE__ .flip h2,
.__UIV_SCOPE__ .flip p {
  transform: translateZ(90px);
  text-shadow: 0 0 3px black;
  text-align: center;
}

.__UIV_SCOPE__ .flip h2 {
  font-size: 3em;
  color: #fff;
  letter-spacing: 1px;
}

.__UIV_SCOPE__ .flip p {
  font-size: 1em;
  color: #eee;
  line-height: 1.6em;
}

.__UIV_SCOPE__ .flip::before,
.__UIV_SCOPE__ .flip::after {
  content: "";
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  position: absolute;
  background-image: linear-gradient(purple, red);
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
  transform: rotateY(180deg)translateZ(1px);
}

.__UIV_SCOPE__ .flip::before {
  transform: none;
  background-image: linear-gradient(violet, orange);
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
}
